import { inferModelVariant } from "./skinVariant";
import type { SteveModelVariant } from "./steveGeo";

interface Rect {
  x: number;
  y: number;
  w: number;
  h: number;
}

interface Part {
  base: Rect;
  slot: Rect;
  overlay?: Rect;
  overlayInLegacy?: boolean;
  legacyBase?: Rect;
}

const BODY_WIDTH = 8;
const LEG_WIDTH = 4;
const HEAD_SIZE = 8;
const LIMB_HEIGHT = 12;
const SLIM_ARM_WIDTH = 3;
const CLASSIC_ARM_WIDTH = 4;

const TORSO_TOP = HEAD_SIZE;
const LEG_TOP = HEAD_SIZE + LIMB_HEIGHT;

export const FLAT_SKIN_HEIGHT = HEAD_SIZE + LIMB_HEIGHT + LIMB_HEIGHT;

const MAX_CACHED_RENDERS = 32;
const INLINE_KEY_LIMIT = 256;

function armWidthOf(variant: SteveModelVariant): number {
  return variant === "slim" ? SLIM_ARM_WIDTH : CLASSIC_ARM_WIDTH;
}

export function flatSkinWidth(variant: SteveModelVariant = "classic"): number {
  return armWidthOf(variant) * 2 + BODY_WIDTH;
}

function partsFor(arm: number): Part[] {
  const bodyLeft = arm;
  const leftArmLeft = arm + BODY_WIDTH;

  return [
    {
      base: { x: 8, y: 8, w: HEAD_SIZE, h: HEAD_SIZE },
      slot: { x: bodyLeft, y: 0, w: HEAD_SIZE, h: HEAD_SIZE },
      overlay: { x: 40, y: 8, w: HEAD_SIZE, h: HEAD_SIZE },
      overlayInLegacy: true,
    },
    {
      base: { x: 20, y: 20, w: BODY_WIDTH, h: LIMB_HEIGHT },
      slot: { x: bodyLeft, y: TORSO_TOP, w: BODY_WIDTH, h: LIMB_HEIGHT },
      overlay: { x: 20, y: 36, w: BODY_WIDTH, h: LIMB_HEIGHT },
    },
    {
      base: { x: 44, y: 20, w: arm, h: LIMB_HEIGHT },
      slot: { x: 0, y: TORSO_TOP, w: arm, h: LIMB_HEIGHT },
      overlay: { x: 44, y: 36, w: arm, h: LIMB_HEIGHT },
    },
    {
      base: { x: 36, y: 52, w: arm, h: LIMB_HEIGHT },
      slot: { x: leftArmLeft, y: TORSO_TOP, w: arm, h: LIMB_HEIGHT },
      overlay: { x: 52, y: 52, w: arm, h: LIMB_HEIGHT },
      legacyBase: { x: 44, y: 20, w: arm, h: LIMB_HEIGHT },
    },
    {
      base: { x: 4, y: 20, w: LEG_WIDTH, h: LIMB_HEIGHT },
      slot: { x: bodyLeft, y: LEG_TOP, w: LEG_WIDTH, h: LIMB_HEIGHT },
      overlay: { x: 4, y: 36, w: LEG_WIDTH, h: LIMB_HEIGHT },
    },
    {
      base: { x: 20, y: 52, w: LEG_WIDTH, h: LIMB_HEIGHT },
      slot: { x: bodyLeft + LEG_WIDTH, y: LEG_TOP, w: LEG_WIDTH, h: LIMB_HEIGHT },
      overlay: { x: 4, y: 52, w: LEG_WIDTH, h: LIMB_HEIGHT },
      legacyBase: { x: 4, y: 20, w: LEG_WIDTH, h: LIMB_HEIGHT },
    },
  ];
}

export class NotASkinTextureError extends Error {
  constructor(width: number, height: number) {
    super(`flat skin: ${width}x${height} is not a Minecraft skin texture`);
    this.name = "NotASkinTextureError";
  }
}

function loadImage(url: string): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error(`flat skin: failed to load texture ${url}`));
    img.src = url;
  });
}

interface Layout {
  texScale: number;
  legacy: boolean;
}

function layoutOf(img: HTMLImageElement): Layout {
  const { width, height } = img;
  if (width < 64 || width % 64 !== 0) throw new NotASkinTextureError(width, height);

  const texScale = width / 64;
  if (height === width) return { texScale, legacy: false };
  if (height * 2 === width) return { texScale, legacy: true };
  throw new NotASkinTextureError(width, height);
}

function draw(
  ctx: CanvasRenderingContext2D,
  img: HTMLImageElement,
  source: Rect,
  slot: Rect,
  texScale: number,
  scale: number,
  mirror: boolean,
): void {
  const sx = source.x * texScale;
  const sy = source.y * texScale;
  const sw = source.w * texScale;
  const sh = source.h * texScale;
  const dx = slot.x * scale;
  const dy = slot.y * scale;
  const dw = slot.w * scale;
  const dh = slot.h * scale;

  if (!mirror) {
    ctx.drawImage(img, sx, sy, sw, sh, dx, dy, dw, dh);
    return;
  }
  ctx.save();
  ctx.translate(dx + dw, dy);
  ctx.scale(-1, 1);
  ctx.drawImage(img, sx, sy, sw, sh, 0, 0, dw, dh);
  ctx.restore();
}

function paint(
  img: HTMLImageElement,
  variant: SteveModelVariant,
  layout: Layout,
  scale: number,
): string {
  const arm = armWidthOf(variant);
  const canvas = document.createElement("canvas");
  canvas.width = flatSkinWidth(variant) * scale;
  canvas.height = FLAT_SKIN_HEIGHT * scale;

  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("flat skin: no 2D context");
  ctx.imageSmoothingEnabled = false;

  for (const part of partsFor(arm)) {
    const mirror = layout.legacy && !!part.legacyBase;
    const base = mirror ? part.legacyBase! : part.base;
    draw(ctx, img, base, part.slot, layout.texScale, scale, mirror);

    if (!part.overlay) continue;
    if (layout.legacy && !part.overlayInLegacy) continue;
    draw(ctx, img, part.overlay, part.slot, layout.texScale, scale, mirror);
  }

  return canvas.toDataURL("image/png");
}

function fingerprint(value: string): string {
  let hash = 5381;
  for (let i = 0; i < value.length; i++) {
    hash = ((hash * 33) ^ value.charCodeAt(i)) >>> 0;
  }
  return `${value.length.toString(36)}.${hash.toString(36)}`;
}

function cacheKeyFor(textureUrl: string, variant: string, scale: number): string {
  const id = textureUrl.length > INLINE_KEY_LIMIT ? fingerprint(textureUrl) : textureUrl;
  return `${id}|${variant}|${scale}`;
}

const cache = new Map<string, Promise<string>>();

function remember(key: string, task: Promise<string>): void {
  cache.set(key, task);
  while (cache.size > MAX_CACHED_RENDERS) {
    const oldest = cache.keys().next();
    if (oldest.done) break;
    cache.delete(oldest.value);
  }
}

export interface FlatSkinOptions {
  variant?: SteveModelVariant;
  scale?: number;
}

export function renderFlatSkin(
  textureUrl: string,
  options: FlatSkinOptions = {},
): Promise<string> {
  const { variant, scale = 16 } = options;
  const key = cacheKeyFor(textureUrl, variant ?? "auto", scale);

  const known = cache.get(key);
  if (known) return known;

  const task = (async () => {
    const img = await loadImage(textureUrl);
    const layout = layoutOf(img);
    return paint(img, variant ?? inferModelVariant(img), layout, scale);
  })().catch((error) => {
    cache.delete(key);
    throw error;
  });

  remember(key, task);
  return task;
}

export function clearFlatSkinCache(): void {
  cache.clear();
}
